"use strict";
// Timers the island owns, and island code that clears the program's.
exports.start = (ms, label) => setTimeout(() => console.log(`island timeout ${label}`), ms);
exports.every = (ms, fn) => setInterval(fn, ms);
exports.soon = (label) => setImmediate(() => console.log(`island immediate ${label}`));
exports.cancel = (t) => clearTimeout(t);
exports.cancelSoon = (i) => clearImmediate(i);
exports.kind = (t) => typeof t;
